// batchDeleteError maps a bulk-delete tally to the process result. When some
// items succeeded and some failed it returns a PartialFailure (exit 7), unless
// --allow-partial-failure is set, in which case it warns and returns nil. A
// total failure propagates firstErr's exit code.
func batchDeleteError(cmd *cobra.Command, succeeded, failed int, firstErr error, noun string) error {
	if failed == 0 {
		return nil
	}
	allow, _ := cmd.Flags().GetBool("allow-partial-failure")
	if succeeded > 0 && allow {
		fmt.Fprintf(os.Stderr, "warning: %d of %d %s failed; continuing (--allow-partial-failure)\n",
			failed, succeeded+failed, noun)
		return nil
	}
	return exitcode.PartialOrPropagate(succeeded, failed, firstErr,
		fmt.Sprintf("%d of %d %s failed", failed, succeeded+failed, noun))
}

// lookupMatchingIDs looks up resources whose nameField equals name and returns
// every matching resource's idField value. It fetches up to 100 candidates so
// callers can detect duplicate-name/serial collisions (e.g. two computer records
// sharing a serial after a logic-board swap), and re-fetches unfiltered when an
// endpoint ignores the RSQL filter param (e.g. prestages). The name is escaped
// to prevent RSQL injection. Returns an empty slice when nothing matches.
func lookupMatchingIDs(ctx context.Context, client registry.HTTPClient, listPath, nameField, idField, name string) ([]string, error) {
	// Escape backslashes before quotes so a value ending in `\` can't
	// neutralize the closing quote and break out of the RSQL string literal.
	escapedName := strings.ReplaceAll(name, `\`, `\\`)
	escapedName = strings.ReplaceAll(escapedName, `"`, `\"`)
	// listPath may already carry a query string (e.g. "?section=HARDWARE" so the
	// filtered field is present in the response) — append with & in that case.
	sep := "?"
	if strings.Contains(listPath, "?") {
		sep = "&"
	}
	filterPath := fmt.Sprintf("%s%sfilter=%s&page-size=100",
		listPath, sep, url.QueryEscape(fmt.Sprintf(`%s=="%s"`, nameField, escapedName)))

	resp, err := client.Do(ctx, "GET", filterPath, nil)
	if err != nil {
		return nil, fmt.Errorf("looking up %q: %w", name, err)
	}
	defer func() { _ = resp.Body.Close() }()

	body, err := io.ReadAll(io.LimitReader(resp.Body, 8<<20))
	if err != nil {
		return nil, fmt.Errorf("reading lookup response: %w", err)
	}

	// Paginated response: {"totalCount": N, "results": [{...}]}
	var data struct {
		TotalCount int               `json:"totalCount"`
		Results    []json.RawMessage `json:"results"`
	}
	if err := json.Unmarshal(body, &data); err != nil {
		// Some endpoints return plain arrays instead of paginated objects
		var arr []json.RawMessage
		if jsonErr := json.Unmarshal(body, &arr); jsonErr != nil {
			return nil, fmt.Errorf("parsing lookup response: %w", err)
		}
		data.Results = arr
		data.TotalCount = len(arr)
	}

	if data.TotalCount == 0 || len(data.Results) == 0 {
		return nil, nil
	}

	// Client-side filter: some endpoints ignore RSQL filter params (e.g. prestages).
	// Always verify the returned results actually match the requested name.
	results := filterResultsByName(data.Results, nameField, name)
	if len(results) == 0 && data.TotalCount > len(data.Results) {
		// RSQL was likely ignored and we only got the first page. Re-fetch all results.
		allPath := fmt.Sprintf("%s%spage-size=%d", listPath, sep, data.TotalCount)
		allResp, err := client.Do(ctx, "GET", allPath, nil)
		if err == nil {
			allBody, _ := io.ReadAll(io.LimitReader(allResp.Body, 8<<20))
			allResp.Body.Close()
			var allData struct {
				Results []json.RawMessage `json:"results"`
			}
			if json.Unmarshal(allBody, &allData) == nil && len(allData.Results) > 0 {
				results = filterResultsByName(allData.Results, nameField, name)
			}
		}
	}

	ids := make([]string, 0, len(results))
	skipped := 0
	for _, raw := range results {
		var obj map[string]any
		if err := json.Unmarshal(raw, &obj); err != nil {
			skipped++
			continue
		}
		id := extractIDString(obj, idField)
		if id == "" {
			skipped++
			continue
		}
		ids = append(ids, id)
	}
	// A matching record we can't resolve to an ID would silently shrink the
	// candidate set and defeat collision detection — surface it instead.
	if skipped > 0 {
		return ids, fmt.Errorf("%d record(s) matched %q but could not be resolved to an ID (missing %q field); target a specific ID", skipped, name, idField)
	}
	return ids, nil
}

// pickMatchingID collapses a set of lookup candidates to a single ID. One match
// returns immediately. Several matches (duplicate names/serials) error under
// --no-input, otherwise prompt the user to choose — so an ambiguous lookup can
// never silently target the wrong record.
func pickMatchingID(ids []string, name string, noInput bool) (string, error) {
	if len(ids) == 1 {
		return ids[0], nil
	}
	// Ambiguous — several records share the value. Only prompt when a human can
	// actually answer: --no-input, or a non-terminal stdin (CI, pipes, non-pty
	// SSH, process supervisors) must fail fast rather than block on a read that
	// will never be satisfied. Usage exit code marks it as a fix-the-invocation
	// condition, distinct from a generic failure, per agent_context.md.
	if noInput || !term.IsTerminal(int(os.Stdin.Fd())) {
		return "", exitcode.New(exitcode.Usage, fmt.Sprintf("multiple resources found matching %q (IDs: %s); resolve the duplicates or target a specific ID", name, strings.Join(ids, ", ")))
	}
	fmt.Fprintf(os.Stderr, "Multiple resources found matching %q:\n", name)
	for i, id := range ids {
		fmt.Fprintf(os.Stderr, "  [%d] ID: %s\n", i+1, id)
	}
	fmt.Fprintf(os.Stderr, "Enter number to select (or 0 to cancel): ")
	var choice int
	if _, err := fmt.Fscan(os.Stdin, &choice); err != nil || choice < 1 || choice > len(ids) {
		return "", fmt.Errorf("aborted")
	}
	return ids[choice-1], nil
}

// resolveNameToID looks up a resource by name (or serial/udid) and returns its
// single matching ID. This enables --name/--serial/--udid as an alternative to
// positional ID args on get/update/patch commands. The nameField parameter
// specifies the filter field (usually "name", but some resources use
// "displayName"). The idField parameter specifies which response property holds
// the identifier (usually "id", but some resources use "templateId", "groupId",
// etc.). Errors when nothing matches, and — unlike a naive first-match lookup —
// errors (or prompts) when several records share the value, so duplicate serial
// numbers can never silently target the wrong record.
func resolveNameToID(ctx context.Context, client registry.HTTPClient, listPath, nameField, idField, name string, noInput bool) (string, error) {
	ids, err := lookupMatchingIDs(ctx, client, listPath, nameField, idField, name)
	if err != nil {
		return "", err
	}
	if len(ids) == 0 {
		return "", fmt.Errorf("no resource found with name %q", name)
	}
	return pickMatchingID(ids, name, noInput)
}

// extractIDString extracts the named identifier field from a JSON object as a string.
// NOTE: Also used by classic_registry.go helpers (same generated package).
func extractIDString(obj map[string]any, field string) string {
	switch v := obj[field].(type) {
	case string:
		return v
	case float64:
		return fmt.Sprintf("%d", int(v))
	default:
		return ""
	}
}

// resolveNestedField resolves a dot-notation field path (e.g. "general.name")
// from a parsed JSON object. Returns the string value and whether the field was
// found. A field is "not found" when any segment of the path is missing (e.g.
// the response didn't include the hardware section).
func resolveNestedField(obj map[string]any, field string) (string, bool) {
	if !strings.Contains(field, ".") {
		if s, ok := obj[field].(string); ok {
			return s, true
		}
		_, exists := obj[field]
		return "", exists
	}
	parts := strings.Split(field, ".")
	var current any = obj
	for _, part := range parts[:len(parts)-1] {
		m, ok := current.(map[string]any)
		if !ok {
			return "", false
		}
		current, ok = m[part]
		if !ok {
			return "", false
		}
	}
	m, ok := current.(map[string]any)
	if !ok {
		return "", false
	}
	v, exists := m[parts[len(parts)-1]]
	if !exists {
		return "", false
	}
	if s, ok := v.(string); ok {
		return s, true
	}
	return "", true
}

// filterResultsByName filters JSON results to those with an exact name match.
// Some API endpoints ignore RSQL filter params (e.g. prestages) and return all
// results. This provides a client-side fallback for accurate name resolution.
// Supports dot-notation fields (e.g. "general.name", "hardware.serialNumber").
// When the field is absent from the response (e.g. the hardware section wasn't
// returned), the result is kept — the server's RSQL filter is trusted.
func filterResultsByName(results []json.RawMessage, nameField, name string) []json.RawMessage {
	var filtered []json.RawMessage
	for _, raw := range results {
		var obj map[string]any
		if err := json.Unmarshal(raw, &obj); err != nil {
			continue
		}
		val, found := resolveNestedField(obj, nameField)
		if !found || val == name {
			filtered = append(filtered, raw)
		}
	}
	return filtered
}

// renameResourceByID performs a fetch-merge-put to set a single field (name)
// on an existing resource. Used for upload-style endpoints whose request body
// schema rejects a name — the token upload runs first, then this helper
// applies the user's --name in a follow-up PUT against the standard update
// path. Read-only fields from the GET response are included in the PUT body;
// Jamf APIs that mark fields readOnly typically ignore them on update.
func renameResourceByID(ctx context.Context, client registry.HTTPClient, updateURL, field, value string) error {
	resp, err := client.Do(ctx, "GET", updateURL, nil)
	if err != nil {
		return fmt.Errorf("fetching existing record: %w", err)
	}
	defer func() { _ = resp.Body.Close() }()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 10<<20))
	if err != nil {
		return fmt.Errorf("reading existing record: %w", err)
	}
	var record map[string]any
	if err := json.Unmarshal(body, &record); err != nil {
		return fmt.Errorf("parsing existing record: %w", err)
	}
	record[field] = value
	putBody, err := json.Marshal(record)
	if err != nil {
		return fmt.Errorf("marshaling rename body: %w", err)
	}
	putResp, err := client.Do(ctx, "PUT", updateURL, bytes.NewReader(putBody))
	if err != nil {
		return fmt.Errorf("PUT rename: %w", err)
	}
	defer func() { _ = putResp.Body.Close() }()
	if putResp.StatusCode >= 400 {
		errBody, _ := io.ReadAll(io.LimitReader(putResp.Body, 64<<10))
		return fmt.Errorf("PUT %s returned %d: %s", updateURL, putResp.StatusCode, string(errBody))
	}
	return nil
}

// setBodyStringField sets a top-level string field on a JSON body, leaving
// other fields untouched. Empty value is a no-op; empty body is bootstrapped
// to {} first. Used to apply a user-supplied --name flag to the request body
// without requiring them to hand-build JSON.
func setBodyStringField(body []byte, field, value string) ([]byte, error) {
	if value == "" {
		return body, nil
	}
	var m map[string]any
	if len(body) > 0 {
		if err := json.Unmarshal(body, &m); err != nil {
			return nil, fmt.Errorf("parsing body JSON: %w", err)
		}
	}
	if m == nil {
		m = make(map[string]any)
	}
	m[field] = value
	return json.Marshal(m)
}

// fileFieldSpec describes one request-body field whose value is sourced from
// a local file. The generator emits these specs inline per operation.
type fileFieldSpec struct {
	FilePath       string // value of the user-facing flag (e.g. --script-file); empty = skip
	Field          string // JSON property to populate (e.g. "scriptContents")
	Encoding       string // "raw" | "base64"
	CompanionField string // optional JSON property auto-filled with filepath.Base(FilePath) when absent
	NameFallback   string // "none" | "keep-ext" | "strip-ext"
	NameField      string // resource's name property (usually "name")
}

// injectFileFields overlays file-sourced fields into a JSON request body.
// If body is empty and at least one file flag is active, a new object is
// constructed. File values overwrite any value already present in the body;
// companion and name fields are only filled when absent.
func injectFileFields(body []byte, specs []fileFieldSpec) ([]byte, error) {
	active := false
	for _, s := range specs {
		if s.FilePath != "" {
			active = true
			break
		}
	}
	if !active {
		return body, nil
	}
	var m map[string]any
	if len(body) > 0 {
		if err := json.Unmarshal(body, &m); err != nil {
			return nil, fmt.Errorf("parsing body JSON: %w", err)
		}
	}
	if m == nil {
		m = make(map[string]any)
	}
	for _, s := range specs {
		if s.FilePath == "" {
			continue
		}
		data, err := os.ReadFile(s.FilePath)
		if err != nil {
			return nil, fmt.Errorf("reading %s: %w", s.FilePath, err)
		}
		switch s.Encoding {
		case "base64":
			m[s.Field] = base64.StdEncoding.EncodeToString(data)
		default:
			m[s.Field] = string(data)
		}
		if s.CompanionField != "" {
			if _, has := m[s.CompanionField]; !has {
				m[s.CompanionField] = filepath.Base(s.FilePath)
			}
		}
		if s.NameFallback != "" && s.NameFallback != "none" && s.NameField != "" {
			if _, has := m[s.NameField]; !has {
				name := filepath.Base(s.FilePath)
				if s.NameFallback == "strip-ext" {
					if idx := strings.LastIndex(name, "."); idx > 0 {
						name = name[:idx]
					}
				}
				m[s.NameField] = name
			}
		}
	}
	out, err := json.Marshal(m)
	if err != nil {
		return nil, fmt.Errorf("re-marshaling body after file-field injection: %w", err)
	}
	return out, nil
}

// removeJSONFields strips the named top-level keys from a JSON object body and
// returns the re-marshaled result. When body is empty or not a JSON object, it is
// returned unchanged. Used by composite apply/update flows that route some fields
// (e.g. encodedToken, tokenFileName) to an auxiliary endpoint and must not
// re-send them to the main body endpoint.
func removeJSONFields(body []byte, fields ...string) ([]byte, error) {
	if len(body) == 0 || len(fields) == 0 {
		return body, nil
	}
	var m map[string]any
	if err := json.Unmarshal(body, &m); err != nil {
		return body, nil // not a JSON object — pass through
	}
	changed := false
	for _, f := range fields {
		if _, ok := m[f]; ok {
			delete(m, f)
			changed = true
		}
	}
	if !changed {
		return body, nil
	}
	if len(m) == 0 {
		return nil, nil
	}
	return json.Marshal(m)
}

// readApplyInput reads input from --from-file or stdin for apply commands.
// NOTE: Also used by classic_registry.go helpers (same generated package).
func readApplyInput(fromFile string) ([]byte, error) {
	if fromFile != "" {
		data, err := os.ReadFile(fromFile)
		if err != nil {
			return nil, fmt.Errorf("reading input file: %w", err)
		}
		return data, nil
	}

	stat, _ := os.Stdin.Stat()
	if (stat.Mode() & os.ModeCharDevice) == 0 {
		data, err := io.ReadAll(io.LimitReader(os.Stdin, 10<<20))
		if err != nil {
			return nil, fmt.Errorf("reading stdin: %w", err)
		}
		if len(data) > 0 {
			return data, nil
		}
	}

	return nil, fmt.Errorf("input required: use --from-file or pipe data to stdin")
}

// printScaffoldOutput prints a scaffold JSON string, converting to YAML when the
// output format requests it.
func printScaffoldOutput(jsonStr, format string) error {
	if format == "yaml" {
		var v any
		if err := json.Unmarshal([]byte(jsonStr), &v); err != nil {
			return fmt.Errorf("scaffold marshal error: %w", err)
		}
		enc := yaml.NewEncoder(os.Stdout)
		enc.SetIndent(2)
		return enc.Encode(v)
	}
	fmt.Println(jsonStr)
	return nil
}

// normalizeInputToJSON converts YAML input to JSON. JSON input is returned unchanged.
func normalizeInputToJSON(data []byte) ([]byte, error) {
	// Fast path: already JSON
	if json.Valid(data) {
		return data, nil
	}
	// Shells like zsh interpret \n in echo output as real newlines (0x0a), producing
	// literal control characters inside JSON string values — invalid JSON. Try
	// escaping those characters and retry before falling back to YAML, which would
	// silently fold them into spaces.
	if fixed := escapeJSONStringLiterals(data); json.Valid(fixed) {
		return fixed, nil
	}
	// Try YAML → any → JSON
	var v any
	if err := yaml.Unmarshal(data, &v); err != nil {
		return nil, fmt.Errorf("input is not valid JSON or YAML: %w", err)
	}
	out, err := json.Marshal(v)
	if err != nil {
		return nil, fmt.Errorf("re-marshaling YAML as JSON: %w", err)
	}
	return out, nil
}

// escapeJSONStringLiterals escapes any U+0000–U+001F control character that
// appears inside a JSON string value. Fixes input produced by shells like zsh
// whose built-in echo interprets \n even in single-quoted strings, creating
// invalid JSON that the YAML fallback would silently mangle.
func escapeJSONStringLiterals(data []byte) []byte {
	var buf bytes.Buffer
	buf.Grow(len(data))
	inString := false
	escaped := false
	for _, b := range data {
		switch {
		case escaped:
			buf.WriteByte(b)
			escaped = false
		case b == '\\' && inString:
			buf.WriteByte(b)
			escaped = true
		case b == '"':
			inString = !inString
			buf.WriteByte(b)
		case inString && b <= 0x1f:
			fmt.Fprintf(&buf, `\u%04x`, b)
		default:
			buf.WriteByte(b)
		}
	}
	return buf.Bytes()
}

// extractJSONField extracts a string field from a JSON object.
// Supports dot-notation fields (e.g. "general.name").
func extractJSONField(data []byte, field string) (string, error) {
	var obj map[string]any
	if err := json.Unmarshal(data, &obj); err != nil {
		return "", fmt.Errorf("parsing JSON: %w", err)
	}
	if strings.Contains(field, ".") {
		val, found := resolveNestedField(obj, field)
		if !found || val == "" {
			return "", fmt.Errorf("field %q not found or empty", field)
		}
		return val, nil
	}
	val, ok := obj[field]
	if !ok {
		return "", fmt.Errorf("field %q not found", field)
	}
	s, ok := val.(string)
	if !ok || s == "" {
		return "", fmt.Errorf("field %q must be a non-empty string", field)
	}
	return s, nil
}

// resolveNameToIDForApply is resolveNameToID for upsert flows: a no-match returns
// ("", nil) so the caller creates the resource instead of erroring. Collisions
// are handled identically to resolveNameToID (error under --no-input, else prompt),
// so a duplicate name never silently replaces the wrong record.
func resolveNameToIDForApply(ctx context.Context, client registry.HTTPClient, listPath, nameField, idField, name string, noInput bool) (string, error) {
	ids, err := lookupMatchingIDs(ctx, client, listPath, nameField, idField, name)
	if err != nil {
		return "", err
	}
	if len(ids) == 0 {
		return "", nil // Not found — caller should create
	}
	return pickMatchingID(ids, name, noInput)
}

// fieldFilter describes the writable fields a PUT request body accepts, derived
// from the OpenAPI request schema at generation time. "update --set" applies it
// to a fetched resource to strip read-only / server-computed fields before the
// merge-put, preventing HTTP 400s from fields the endpoint does not accept.
//
// A nil *fieldFilter (or one whose fields map is nil) means "keep everything" —
// emitted where the schema is open/unmodelled so nothing is over-filtered. A map
// entry with a nil value is a leaf (scalar, array, or opaque object): kept whole.
// A non-nil value recurses into a nested object.
type fieldFilter struct {
	fields map[string]*fieldFilter
}

func (f *fieldFilter) apply(data map[string]any) {
	if f == nil || f.fields == nil {
		return
	}
	for k := range data {
		child, ok := f.fields[k]
		if !ok {
			delete(data, k)
			continue
		}
		if child != nil {
			if sub, ok := data[k].(map[string]any); ok {
				child.apply(sub)
			}
		}
	}
}

// deepMergeJSON recursively merges src into dst: object values merge key-by-key,
// every other value (scalar, array, null) replaces. Used by "update --set".
func deepMergeJSON(dst, src map[string]any) {
	for k, v := range src {
		if sv, ok := v.(map[string]any); ok {
			if dv, ok := dst[k].(map[string]any); ok {
				deepMergeJSON(dv, sv)
				continue
			}
		}
		dst[k] = v
	}
}

// fetchForMerge GETs a resource and returns its raw JSON body. "update --set"
// uses it to read current state before merging caller changes and PUTting back.
func fetchForMerge(ctx context.Context, client registry.HTTPClient, getPath string) ([]byte, error) {
	resp, err := client.Do(ctx, "GET", getPath, nil)
	if err != nil {
		return nil, fmt.Errorf("fetching current state for --set: %w", err)
	}
	defer func() { _ = resp.Body.Close() }()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 10<<20))
	if err != nil {
		return nil, fmt.Errorf("reading current state for --set: %w", err)
	}
	if resp.StatusCode >= 400 {
		return nil, fmt.Errorf("fetching current state for --set: GET %s returned %d: %s", getPath, resp.StatusCode, string(body))
	}
	return body, nil
}

// buildMergePatchFromSet converts a slice of "key.path=value" strings into a
// JSON merge-patch document. Dot notation is expanded into nested objects.
// Value inference: "true"/"false" → bool, "null" → null, integers → int64, else string.
func buildMergePatchFromSet(pairs []string) ([]byte, error) {
	result := make(map[string]any)
	for _, pair := range pairs {
		eq := strings.Index(pair, "=")
		if eq < 1 {
			return nil, fmt.Errorf("invalid --set value %q: expected key=value", pair)
		}
		key := pair[:eq]
		val := pair[eq+1:]
		if err := setNestedValue(result, strings.Split(key, "."), parsePatchValue(val)); err != nil {
			return nil, fmt.Errorf("setting %q: %w", key, err)
		}
	}
	return json.Marshal(result)
}

// setNestedValue sets a value at a dot-notation path within a nested map.
func setNestedValue(m map[string]any, keys []string, value any) error {
	if len(keys) == 1 {
		m[keys[0]] = value
		return nil
	}
	sub, ok := m[keys[0]]
	if !ok {
		sub = make(map[string]any)
		m[keys[0]] = sub
	}
	subMap, ok := sub.(map[string]any)
	if !ok {
		return fmt.Errorf("cannot set nested key under non-object field %q", keys[0])
	}
	return setNestedValue(subMap, keys[1:], value)
}

// parsePatchValue converts a string to the most appropriate scalar type for
// JSON merge-patch: "true"/"false" → bool, "null" → nil, integers → int64, else string.
func parsePatchValue(s string) any {
	switch s {
	case "true":
		return true
	case "false":
		return false
	case "null":
		return nil
	}
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		return i
	}
	return s
}

// fetchVersionLock GETs a resource and returns the raw response body.
// The caller uses this to extract versionLock values for optimistic locking.
func fetchVersionLock(ctx context.Context, client registry.HTTPClient, getPath string) ([]byte, error) {
	resp, err := client.Do(ctx, "GET", getPath, nil)
	if err != nil {
		return nil, fmt.Errorf("fetching resource for version lock: %w", err)
	}
	defer func() { _ = resp.Body.Close() }()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return nil, fmt.Errorf("reading version lock response: %w", err)
	}
	return body, nil
}

// injectVersionLocks deep-merges all versionLock fields from a GET response
// into the user-provided request body. This ensures optimistic locking fields
// are current without requiring users to manually fetch and set them.
func injectVersionLocks(data, serverResponse []byte) ([]byte, error) {
	var dst, src map[string]any
	if err := json.Unmarshal(data, &dst); err != nil {
		return data, nil // unparseable input — pass through unchanged
	}
	if err := json.Unmarshal(serverResponse, &src); err != nil {
		return data, fmt.Errorf("parsing server response for version lock: %w", err)
	}
	mergeVersionLocks(dst, src)
	out, err := json.Marshal(dst)
	if err != nil {
		return data, nil
	}
	return out, nil
}

// mergeVersionLocks recursively copies versionLock fields from src into dst.
func mergeVersionLocks(dst, src map[string]any) {
	if vl, ok := src["versionLock"]; ok {
		dst["versionLock"] = vl
	}
	for key, srcVal := range src {
		srcObj, ok := srcVal.(map[string]any)
		if !ok {
			continue
		}
		dstVal, ok := dst[key]
		if !ok {
			continue
		}
		dstObj, ok := dstVal.(map[string]any)
		if !ok {
			continue
		}
		mergeVersionLocks(dstObj, srcObj)
	}
}

// setVersionLockZero recursively sets all versionLock fields to 0 in the JSON document.
// Used when creating new resources that require optimistic locking.
func setVersionLockZero(data []byte) []byte {
	var obj map[string]any
	if err := json.Unmarshal(data, &obj); err != nil {
		return data
	}
	zeroVersionLocks(obj)
	out, err := json.Marshal(obj)
	if err != nil {
		return data
	}
	return out
}

// zeroVersionLocks recursively sets all versionLock fields to 0.
func zeroVersionLocks(obj map[string]any) {
	if _, ok := obj["versionLock"]; ok {
		obj["versionLock"] = 0
	}
	for _, v := range obj {
		if nested, ok := v.(map[string]any); ok {
			zeroVersionLocks(nested)
		}
	}
}

// tableColumn defines a preferred column for list table output.
type tableColumn struct {
	field string
	label string
}

// selectTableColumns transforms a JSON array to include only the specified
// columns with display labels. Only applies for table/csv/plain formats;
// JSON/YAML output is returned unchanged.
func selectTableColumns(data []byte, columns []tableColumn, format string) []byte {
	if format == "json" || format == "yaml" || format == "xml" || format == "raw" || format == "ndjson" {
		return data
	}

	var items []json.RawMessage
	if err := json.Unmarshal(data, &items); err != nil {
		return data
	}

	result := make([]map[string]any, 0, len(items))
	for _, raw := range items {
		var obj map[string]any
		if err := json.Unmarshal(raw, &obj); err != nil {
			continue
		}
		row := make(map[string]any, len(columns))
		for _, col := range columns {
			row[col.label] = resolveFieldValue(obj, col.field)
		}
		result = append(result, row)
	}

	out, err := json.Marshal(result)
	if err != nil {
		return data
	}
	return out
}

// resolveFieldValue extracts a value from a JSON object using a dot-notation
// field path (e.g. "general.name"). Returns nil if any segment is missing.
func resolveFieldValue(obj map[string]any, field string) any {
	if !strings.Contains(field, ".") {
		return obj[field]
	}
	parts := strings.Split(field, ".")
	var current any = obj
	for _, part := range parts[:len(parts)-1] {
		m, ok := current.(map[string]any)
		if !ok {
			return nil
		}
		current = m[part]
	}
	m, ok := current.(map[string]any)
	if !ok {
		return nil
	}
	return m[parts[len(parts)-1]]
}

// readDeleteFile reads a file of IDs or names for bulk delete.
// Lines beginning with '#' and blank lines are ignored.
func readDeleteFile(path string) ([]string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("reading %q: %w", path, err)
	}
	var entries []string
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		entries = append(entries, line)
	}
	return entries, nil
}

// isNumericID returns true when s consists entirely of ASCII digits.
func isNumericID(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

// versionFallback tracks which API version was resolved for a resource path so
// that paginated calls reuse the same version across pages without re-probing.
type versionFallback struct {
	templatePath string // original spec path, e.g. /v3/foo/{id}
	activePath   string // resolved base path after first successful call
	warned       bool   // true after the fallback warning has been emitted once
}

func newVersionFallback(templatePath string) *versionFallback {
	return &versionFallback{templatePath: templatePath, activePath: templatePath}
}

// do calls client.Do with the primary actualPath. On 404 it retries each
// fallback in order, emitting a one-line stderr warning on the first successful
// retry. Subsequent calls reuse the resolved path directly (safe for pagination).
func (v *versionFallback) do(client registry.HTTPClient, ctx context.Context, method, actualPath string, body []byte, fallbacks []string) (*http.Response, error) {
	if v.activePath != v.templatePath {
		adjusted := versionFallbackApply(v.templatePath, v.activePath, actualPath)
		return versionFallbackDo(client, ctx, method, adjusted, body)
	}
	resp, err := versionFallbackDo(client, ctx, method, actualPath, body)
	if err == nil || !versionFallbackIs404(err) || len(fallbacks) == 0 {
		return resp, err
	}
	for _, fb := range fallbacks {
		fbActual := versionFallbackApply(v.templatePath, fb, actualPath)
		fbResp, fbErr := versionFallbackDo(client, ctx, method, fbActual, body)
		if fbErr == nil {
			if !v.warned {
				fmt.Fprintf(os.Stderr, "warning: %s %s returned 404; falling back to %s (tenant may be on older Jamf Pro)\n", method, actualPath, fbActual)
				v.warned = true
			}
			v.activePath = fb
			return fbResp, nil
		}
		if !versionFallbackIs404(fbErr) {
			return nil, fbErr
		}
	}
	return nil, err // original 404, all fallbacks exhausted
}

func versionFallbackDo(client registry.HTTPClient, ctx context.Context, method, path string, body []byte) (*http.Response, error) {
	var br io.Reader
	if body != nil {
		br = bytes.NewReader(body)
	}
	return client.Do(ctx, method, path, br)
}

func versionFallbackIs404(err error) bool {
	var e *exitcode.Error
	return errors.As(err, &e) && e.Code == exitcode.NotFound
}

var versionSegRe = regexp.MustCompile(`^(/v\d+|/preview)`)

// versionFallbackApply derives the fallback actual path by replacing the primary
// version prefix with the fallback version prefix. Query params and path-param
// substitutions are preserved because only the leading /vN/ segment changes.
func versionFallbackApply(primaryTemplate, fallbackTemplate, actualPath string) string {
	pv := versionSegRe.FindString(primaryTemplate)
	fv := versionSegRe.FindString(fallbackTemplate)
	if pv == "" || pv == fv {
		return actualPath
	}
	if fv == "" {
		return strings.Replace(actualPath, pv+"/", "/", 1)
	}
	return strings.Replace(actualPath, pv+"/", fv+"/", 1)
}

// fetchClassicGroupMemberIDs and classicFindIDByName are defined in classic_registry.go
// (same package, generated from classicRegistryTemplate).
